@layer moduix.components {
  @keyframes date-picker-content-open {
    from {
      opacity: var(
        --moduix-date-picker-content-closed-opacity,
        var(--moduix-popup-motion-starting-opacity, 0)
      );
      translate: var(--moduix-popup-motion-starting-translate-x, 0)
        var(--moduix-popup-motion-starting-translate-y, 0);
      transform: scale(
        var(
          --moduix-date-picker-content-closed-scale,
          var(--moduix-popup-motion-starting-scale, var(--moduix-scale-popup))
        )
      );
    }

    to {
      opacity: 1;
      translate: 0 0;
      transform: scale(1);
    }
  }

  @keyframes date-picker-content-closed {
    from {
      opacity: 1;
      translate: 0 0;
      transform: scale(1);
    }

    to {
      opacity: var(
        --moduix-date-picker-content-closed-opacity,
        var(--moduix-popup-motion-ending-opacity, 0)
      );
      translate: var(--moduix-popup-motion-ending-translate-x, 0)
        var(--moduix-popup-motion-ending-translate-y, 0);
      transform: scale(
        var(
          --moduix-date-picker-content-closed-scale,
          var(--moduix-popup-motion-ending-scale, var(--moduix-scale-popup))
        )
      );
    }
  }

  .root {
    box-sizing: border-box;
    display: inline-flex;
    width: var(--moduix-date-picker-width, 18.75rem);
    max-width: var(--moduix-date-picker-max-width, 100%);
    flex-direction: column;
    align-items: flex-start;
    gap: var(--moduix-date-picker-root-gap, var(--moduix-spacing-1));
    color: var(--moduix-date-picker-color, var(--moduix-color-foreground));

    &:has(.input[data-index='1']) {
      width: var(--moduix-date-picker-width, 24rem);
    }

    &:is([data-disabled], [data-readonly]) {
      opacity: var(--moduix-date-picker-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .label {
    display: inline-flex;
    align-items: center;
    color: var(
      --moduix-date-picker-label-color,
      var(--moduix-date-picker-color, var(--moduix-color-foreground))
    );
    font-size: var(--moduix-date-picker-label-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-date-picker-label-font-weight, var(--moduix-weight-medium));
    line-height: var(--moduix-date-picker-label-line-height, var(--moduix-line-height-text-sm));
    user-select: none;
  }

  .control {
    position: relative;
    display: flex;
    width: 100%;
    min-width: 0;
    align-items: center;
    gap: var(--moduix-date-picker-input-gap, var(--moduix-spacing-2));
    color: var(--moduix-date-picker-color, var(--moduix-color-foreground));
  }

  .input {
    box-sizing: border-box;
    flex: 1 1 0;
    width: 100%;
    min-width: min(var(--moduix-date-picker-input-min-width, 7.5rem), 100%);
    height: var(--moduix-date-picker-control-height, var(--moduix-size-md));
    margin: 0;
    border: var(--moduix-date-picker-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-date-picker-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-date-picker-radius, var(--moduix-radius-md));
    padding-block: var(--moduix-date-picker-input-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-date-picker-input-padding-x-start, var(--moduix-spacing-3-5))
      var(--moduix-date-picker-input-padding-x-end, 4.25rem);
    background-color: var(--moduix-date-picker-bg, var(--moduix-color-background));
    color: inherit;
    font: inherit;
    font-size: var(--moduix-date-picker-font-size, var(--moduix-text-md));
    line-height: var(--moduix-date-picker-line-height, var(--moduix-line-height-text-md));
    outline: var(
        --moduix-date-picker-focus-ring-width,
        var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
      )
      solid transparent;
    outline-offset: calc(
      var(
          --moduix-date-picker-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        ) *
        -1
    );
    transition:
      background-color var(--moduix-date-picker-transition, var(--moduix-transition-default)),
      border-color var(--moduix-date-picker-transition, var(--moduix-transition-default)),
      color var(--moduix-date-picker-transition, var(--moduix-transition-default)),
      outline-color var(--moduix-date-picker-transition, var(--moduix-transition-default)),
      opacity var(--moduix-date-picker-transition, var(--moduix-transition-default));

    &::placeholder {
      color: var(--moduix-date-picker-placeholder-color, var(--moduix-color-muted-foreground));
      opacity: 1;
    }

    &:focus,
    .control[data-focus] & {
      border-color: var(--moduix-date-picker-focus-ring-color, var(--moduix-color-ring));
      outline-color: var(--moduix-date-picker-focus-ring-color, var(--moduix-color-ring));
    }

    &:is([data-invalid], [aria-invalid='true']),
    .control[data-invalid] & {
      border-color: var(--moduix-date-picker-invalid-color, var(--moduix-color-destructive));
      outline-color: var(--moduix-date-picker-invalid-color, var(--moduix-color-destructive));
    }

    &:is([disabled], [data-disabled], [readonly], [data-readonly]) {
      cursor: default;
    }
  }

  .control:has(.input[data-index='1']) .input {
    min-width: min(var(--moduix-date-picker-range-input-min-width, 7.5rem), 100%);
    padding-inline-end: var(--moduix-date-picker-input-padding-x-start, var(--moduix-spacing-3-5));
  }

  .control .input[data-index='1'] {
    padding-inline-end: var(--moduix-date-picker-input-padding-x-end, 4.25rem);
  }

  .trigger,
  .navTrigger,
  .viewTrigger,
  .presetTrigger {
    box-sizing: border-box;
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    margin: 0;
    border: 0;
    border-radius: var(--moduix-date-picker-action-radius, var(--moduix-radius-sm));
    padding: 0;
    background: var(--moduix-date-picker-action-bg, transparent);
    color: var(--moduix-date-picker-icon-color, var(--moduix-color-muted-foreground));
    font: inherit;
    line-height: 0;
    outline: var(
        --moduix-date-picker-action-focus-ring-width,
        var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
      )
      solid transparent;
    outline-offset: var(--moduix-date-picker-action-focus-ring-offset, 0);
    cursor: pointer;
    transition:
      background-color var(--moduix-date-picker-transition, var(--moduix-transition-default)),
      color var(--moduix-date-picker-transition, var(--moduix-transition-default)),
      outline-color var(--moduix-date-picker-transition, var(--moduix-transition-default)),
      opacity var(--moduix-date-picker-transition, var(--moduix-transition-default));

    & > svg {
      display: block;
      width: var(--moduix-date-picker-icon-size, var(--moduix-spacing-4));
      height: var(--moduix-date-picker-icon-size, var(--moduix-spacing-4));
    }

    &:is(:focus-visible, [data-focus]) {
      outline-color: var(--moduix-date-picker-focus-ring-color, var(--moduix-color-ring));
    }

    &:is([disabled], [data-disabled]) {
      cursor: default;
      opacity: var(--moduix-date-picker-disabled-opacity, var(--moduix-opacity-disabled));
    }

    &[hidden] {
      display: none;
    }

    &:not(:is([disabled], [data-disabled])) {
      @media (hover: hover) {
        &:hover {
          background-color: var(--moduix-date-picker-action-bg-hover, var(--moduix-color-muted));
          color: var(--moduix-date-picker-action-color-hover, var(--moduix-color-foreground));
        }
      }
    }
  }

  .trigger {
    position: absolute;
    top: 50%;
    width: var(--moduix-date-picker-action-size, var(--moduix-size-xs));
    height: var(--moduix-date-picker-action-size, var(--moduix-size-xs));
    inset-inline-end: var(--moduix-date-picker-trigger-offset-right, var(--moduix-spacing-2));
    transform: translateY(-50%);
  }

  .clearTrigger {
    --moduix-close-button-size: var(--moduix-date-picker-action-size, var(--moduix-size-xs));
    --moduix-close-button-icon-size: var(--moduix-date-picker-icon-size, var(--moduix-spacing-4));
    --moduix-close-button-radius: var(--moduix-date-picker-action-radius, var(--moduix-radius-sm));
    --moduix-close-button-bg: var(--moduix-date-picker-action-bg, transparent);
    --moduix-close-button-bg-hover: var(
      --moduix-date-picker-action-bg-hover,
      var(--moduix-color-muted)
    );
    --moduix-close-button-color: var(
      --moduix-date-picker-icon-color,
      var(--moduix-color-muted-foreground)
    );
    --moduix-close-button-color-hover: var(
      --moduix-date-picker-action-color-hover,
      var(--moduix-color-foreground)
    );
    --moduix-close-button-disabled-opacity: var(
      --moduix-date-picker-disabled-opacity,
      var(--moduix-opacity-disabled)
    );
    --moduix-close-button-focus-ring-width: var(
      --moduix-date-picker-action-focus-ring-width,
      var(--moduix-border-width-sm)
    );
    --moduix-close-button-focus-ring-color: var(
      --moduix-date-picker-focus-ring-color,
      var(--moduix-color-ring)
    );
    --moduix-close-button-focus-ring-offset: var(--moduix-date-picker-action-focus-ring-offset, 0);
    position: absolute;
    top: 50%;
    inset-inline-end: calc(
      var(--moduix-date-picker-trigger-offset-right, var(--moduix-spacing-2)) +
        var(--moduix-date-picker-action-size, var(--moduix-size-xs)) +
        var(--moduix-date-picker-action-gap, var(--moduix-spacing-0-5))
    );
    transform: translateY(-50%);

    &[data-focus] {
      outline: var(--moduix-close-button-focus-ring-width) solid
        var(--moduix-close-button-focus-ring-color);
      outline-offset: var(--moduix-close-button-focus-ring-offset);
    }

    &[hidden] {
      display: none;
    }
  }

  .positioner {
    z-index: var(--z-index);
    outline: 0;
  }

  .content {
    box-sizing: border-box;
    z-index: calc(var(--moduix-z-popup) + var(--layer-index, 0));
    width: min(var(--moduix-date-picker-content-width, 20rem), var(--available-width));
    min-width: min(var(--moduix-date-picker-content-min-width, 20rem), var(--available-width));
    max-width: min(
      var(--moduix-date-picker-content-max-width, calc(100vw - 2rem)),
      var(--available-width)
    );
    border: var(--moduix-date-picker-content-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-date-picker-content-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-date-picker-content-radius, var(--moduix-radius-md));
    padding: var(--moduix-date-picker-content-padding, var(--moduix-spacing-3));
    background-color: var(--moduix-date-picker-content-bg, var(--moduix-color-popover));
    box-shadow: var(--moduix-date-picker-content-shadow, var(--moduix-shadow-lg));
    color: var(--moduix-date-picker-content-color, var(--moduix-color-popover-foreground));
    transform-origin: var(--transform-origin);
    outline: 0;

    &[data-state='open'] {
      animation: date-picker-content-open
        var(
          --moduix-date-picker-transition,
          var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
            var(--moduix-popup-motion-easing, var(--moduix-ease-in-out))
        );
    }

    &[data-state='closed'] {
      animation: date-picker-content-closed
        var(
          --moduix-date-picker-transition,
          var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
            var(--moduix-popup-motion-easing, var(--moduix-ease-in-out))
        );
      pointer-events: none;
    }

    @media (prefers-reduced-motion: reduce) {
      &[data-state] {
        animation-delay: 0ms;
        animation-duration: 1ms;
      }
    }
  }

  .content[data-inline] {
    min-width: var(--moduix-date-picker-inline-content-min-width, 18rem);
    box-shadow: var(--moduix-date-picker-inline-content-shadow, none);
  }

  .view {
    display: grid;
    gap: var(--moduix-date-picker-view-gap, var(--moduix-spacing-3));
  }

  .viewControl {
    display: flex;
    min-width: 0;
    align-items: center;
    justify-content: space-between;
    gap: var(--moduix-date-picker-view-control-gap, var(--moduix-spacing-2));
  }

  .navTrigger {
    width: var(--moduix-date-picker-nav-trigger-size, var(--moduix-size-sm));
    height: var(--moduix-date-picker-nav-trigger-size, var(--moduix-size-sm));
  }

  .viewTrigger {
    min-width: 0;
    min-height: var(--moduix-date-picker-view-trigger-height, var(--moduix-size-sm));
    flex: 1;
    gap: var(--moduix-date-picker-view-trigger-gap, var(--moduix-spacing-2));
    padding-inline: var(--moduix-date-picker-view-trigger-padding-x, var(--moduix-spacing-2));
    color: var(--moduix-date-picker-view-trigger-color, var(--moduix-color-foreground));
    font-size: var(--moduix-date-picker-view-trigger-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-date-picker-view-trigger-font-weight, var(--moduix-weight-medium));
    line-height: var(
      --moduix-date-picker-view-trigger-line-height,
      var(--moduix-line-height-text-sm)
    );
  }

  .rangeText,
  .valueText {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .table {
    width: 100%;
    border-collapse: separate;
    border-spacing: var(--moduix-date-picker-table-cell-gap, var(--moduix-spacing-0-5));
    table-layout: fixed;
  }

  .tableHeader,
  .weekNumberCell {
    width: var(--moduix-date-picker-table-cell-size, var(--moduix-size-sm));
    height: var(--moduix-date-picker-table-header-height, 1.75rem);
    color: var(--moduix-date-picker-table-header-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-date-picker-table-header-font-size, var(--moduix-text-xs));
    font-weight: var(--moduix-date-picker-table-header-font-weight, var(--moduix-weight-medium));
    line-height: var(
      --moduix-date-picker-table-header-line-height,
      var(--moduix-line-height-text-xs)
    );
    text-align: center;
  }

  .tableCell {
    width: var(--moduix-date-picker-table-cell-size, var(--moduix-size-sm));
    height: var(--moduix-date-picker-table-cell-size, var(--moduix-size-sm));
    padding: 0;
    text-align: center;
  }

  .weekNumberCell {
    color: var(--moduix-date-picker-week-number-color, var(--moduix-color-muted-foreground));
    font-variant-numeric: tabular-nums;
  }

  .tableCellTrigger {
    box-sizing: border-box;
    display: inline-flex;
    width: 100%;
    min-width: var(--moduix-date-picker-table-cell-size, var(--moduix-size-sm));
    height: var(--moduix-date-picker-table-cell-size, var(--moduix-size-sm));
    align-items: center;
    justify-content: center;
    border: var(--moduix-date-picker-table-cell-border-width, 0) solid
      var(--moduix-date-picker-table-cell-border-color, transparent);
    border-radius: var(--moduix-date-picker-table-cell-radius, var(--moduix-radius-sm));
    padding: 0;
    background: var(--moduix-date-picker-table-cell-bg, transparent);
    color: var(
      --moduix-date-picker-table-cell-color,
      var(--moduix-date-picker-content-color, var(--moduix-color-foreground))
    );
    font: inherit;
    font-size: var(--moduix-date-picker-table-cell-font-size, var(--moduix-text-sm));
    line-height: var(
      --moduix-date-picker-table-cell-line-height,
      var(--moduix-line-height-text-sm)
    );
    outline: var(
        --moduix-date-picker-table-cell-focus-ring-width,
        var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
      )
      solid transparent;
    outline-offset: calc(
      var(
          --moduix-date-picker-table-cell-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        ) *
        -1
    );
    cursor: pointer;
    transition:
      background-color var(--moduix-date-picker-transition, var(--moduix-transition-default)),
      border-color var(--moduix-date-picker-transition, var(--moduix-transition-default)),
      color var(--moduix-date-picker-transition, var(--moduix-transition-default)),
      outline-color var(--moduix-date-picker-transition, var(--moduix-transition-default)),
      opacity var(--moduix-date-picker-transition, var(--moduix-transition-default));

    &:is(:focus-visible, [data-focus]) {
      outline-color: var(
        --moduix-date-picker-table-cell-focus-ring-color,
        var(--moduix-color-ring)
      );
    }

    &[data-today] {
      border-color: var(
        --moduix-date-picker-table-cell-today-border-color,
        var(--moduix-color-ring)
      );
      color: var(
        --moduix-date-picker-table-cell-today-color,
        var(--moduix-date-picker-table-cell-color, var(--moduix-color-foreground))
      );
    }

    &:is([data-in-range], [data-in-hover-range]) {
      background-color: var(--moduix-date-picker-table-cell-range-bg, var(--moduix-color-muted));
      color: var(--moduix-date-picker-table-cell-range-color, var(--moduix-color-foreground));
    }

    &[data-selected] {
      background-color: var(
        --moduix-date-picker-table-cell-selected-bg,
        var(--moduix-color-primary)
      );
      color: var(
        --moduix-date-picker-table-cell-selected-color,
        var(--moduix-color-primary-foreground)
      );
    }

    &:is([data-outside-range], [data-unavailable]) {
      color: var(--moduix-date-picker-table-cell-muted-color, var(--moduix-color-muted-foreground));
    }

    &:is([data-disabled], [disabled]) {
      cursor: default;
      opacity: var(--moduix-date-picker-disabled-opacity, var(--moduix-opacity-disabled));
    }

    &:not(:is([data-disabled], [disabled], [data-selected])) {
      @media (hover: hover) {
        &:hover {
          background-color: var(
            --moduix-date-picker-table-cell-bg-hover,
            var(--moduix-color-accent)
          );
          color: var(
            --moduix-date-picker-table-cell-color-hover,
            var(--moduix-color-accent-foreground)
          );
        }
      }
    }
  }

  .selectControl {
    position: relative;
    display: grid;
    width: 100%;
    max-width: 100%;
    min-width: 0;
  }

  .select {
    box-sizing: border-box;
    flex: 1 1 0;
    width: var(--moduix-date-picker-select-width, var(--moduix-select-width, 100%));
    max-width: var(--moduix-date-picker-select-max-width, var(--moduix-select-max-width, 100%));
    min-width: 0;
    height: var(
      --moduix-date-picker-select-height,
      var(--moduix-select-control-height, var(--moduix-size-sm))
    );
    border: var(--moduix-date-picker-select-border-width, var(--moduix-border-width-sm)) solid
      var(
        --moduix-date-picker-select-border-color,
        var(--moduix-select-border-color, var(--moduix-color-border))
      );
    border-radius: var(
      --moduix-date-picker-select-radius,
      var(--moduix-select-radius, var(--moduix-radius-md))
    );
    padding-block: var(--moduix-date-picker-select-padding-y, var(--moduix-spacing-1));
    padding-inline-start: var(
      --moduix-date-picker-select-padding-x-start,
      var(--moduix-select-trigger-padding-x-start, var(--moduix-spacing-3-5))
    );
    padding-inline-end: calc(
      var(
          --moduix-date-picker-select-action-offset-right,
          var(--moduix-select-action-offset-right, var(--moduix-spacing-2))
        ) +
        var(
          --moduix-date-picker-select-action-size,
          var(--moduix-select-action-size, var(--moduix-size-xs))
        ) +
        var(
          --moduix-date-picker-select-padding-x-start,
          var(--moduix-select-trigger-padding-x-start, var(--moduix-spacing-3-5))
        )
    );
    appearance: none;
    background-color: var(
      --moduix-date-picker-select-bg,
      var(--moduix-select-bg, var(--moduix-color-background))
    );
    color: var(
      --moduix-date-picker-select-color,
      var(--moduix-select-color, var(--moduix-color-foreground))
    );
    font: inherit;
    font-size: var(--moduix-date-picker-select-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-date-picker-select-line-height, var(--moduix-line-height-text-sm));
    outline: var(
        --moduix-date-picker-select-focus-ring-width,
        var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
      )
      solid transparent;
    outline-offset: calc(
      var(
          --moduix-date-picker-select-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        ) *
        -1
    );
    cursor: pointer;
    transition:
      background-color var(--moduix-date-picker-transition, var(--moduix-transition-default)),
      border-color var(--moduix-date-picker-transition, var(--moduix-transition-default)),
      outline-color var(--moduix-date-picker-transition, var(--moduix-transition-default)),
